use caliper_docgen_core::pipeline::{extract, HtmlAttributeMode, PipelineOptions, WatchSession};
use camino::Utf8PathBuf;
use tempfile::TempDir;

fn mk(files: &[(&str, &str)]) -> (TempDir, Utf8PathBuf) {
    let tmp = TempDir::new_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let root = Utf8PathBuf::from_path_buf(tmp.path().to_owned()).unwrap();
    for (n, s) in files {
        let p = root.join(n);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, s).unwrap();
    }
    (tmp, root)
}
fn opts(root: &Utf8PathBuf) -> PipelineOptions {
    PipelineOptions {
        src_dirs: vec![root.join("src")],
        cache_dir: Some(root.join(".cache")),
        html_attributes: HtmlAttributeMode::Full,
        ..Default::default()
    }
}
const C: &str = "import * as React from 'react';\nexport const Box = (props: React.ComponentProps<'div'>) => <div />;\n";

#[test]
fn edit_augment_in_session() {
    let (_t, root) = mk(&[
        ("src/C.tsx", C),
        ("src/a.d.ts", "declare module 'react' { interface HTMLAttributes<T> { tw?: string } }\n"),
    ]);
    let s = WatchSession::lazy(opts(&root));
    drop(s.initialize());
    assert!(s.component("Box").unwrap().entry.props.contains_key("tw"));
    std::fs::write(root.join("src/a.d.ts"), "declare module 'react' { interface HTMLAttributes<T> { tw2?: string } }\n")
        .unwrap();
    let _ = s.update_file(&root.join("src/a.d.ts"));
    let e = s.component("Box").unwrap().entry;
    eprintln!("props: {:?}", e.props.keys().collect::<Vec<_>>());
    assert!(e.props.contains_key("tw2"), "stale after edit");
    assert!(!e.props.contains_key("tw"));
}

